<template><main class="secure-message"><h1>Office check-in help</h1><p v-if="loading">Opening secure message…</p><p v-else-if="error" role="alert">{{error}}</p><article v-else-if="message"><dl><dt>From</dt><dd>{{message.from}}</dd><dt>To</dt><dd>{{message.to}}</dd><dt>CC</dt><dd>{{message.cc}}</dd><dt>Office</dt><dd>{{message.location}}</dd></dl><div class="body">{{message.message}}</div><p>This message is stored encrypted and is available only to its authorized support team and selected provider.</p><router-link v-if="['admin','super_admin','support'].includes(auth.user?.role)" :to="`/tickets?status=open&ticketId=${message.ticketId}`">Open support ticket to follow up</router-link></article></main></template>
<script setup>import {ref,watch,onUnmounted} from 'vue';import {useRoute} from 'vue-router';import {useAuthStore} from '../store/auth';import api from '../services/api';const route=useRoute(),auth=useAuthStore(),message=ref(null),loading=ref(true),error=ref('');let generation=0;watch(()=>route.params.id,async id=>{const version=++generation;message.value=null;loading.value=true;error.value='';try{const {data}=await api.get(`/kiosk/support-messages/${id}`);if(version===generation)message.value=data;}catch{if(version===generation)error.value='This message is unavailable or you do not have access.';}finally{if(version===generation)loading.value=false;}},{immediate:true});onUnmounted(()=>{generation++;message.value=null;});</script>
<style scoped>.secure-message{max-width:850px;margin:auto;padding:40px 24px}article{border:1px solid #d7e4d7;border-radius:18px;padding:28px;background:white}dl{display:grid;grid-template-columns:70px 1fr;gap:12px}dd{margin:0;overflow-wrap:anywhere}.body{white-space:pre-wrap;line-height:1.7;border-top:1px solid #dde5db;padding-top:25px;margin-top:25px}article>p{font-size:12px;color:#63735f;line-height:1.7}</style>
